FUNCTION_BLOCK FB_CSP_MoltenSaltReceiver_FluxPump
(*
========================================================================================
 CYBER-PHYSICAL SYSTEM AUTOMATION SPECIFICATION:
 CONCENTRATED SOLAR POWER (CSP) CENTRAL RECEIVER TOWER - CAVITY ABSORBER
 MULTI-ZONE FLUX-PROFILE SYNCHRONIZATION & COLD SALT BOOSTER PUMP SPEED REGULATION
========================================================================================
 Physical Process Architecture:
  - Working Fluid: High-Temperature Solar Salt eutectic binary mixture (60 wt% NaNO3 / 40 wt% KNO3)
  - Critical Thermal Boundaries:
      * Solidification / Salt Freezing Knee: 221.0 [deg C] (Hard Lockout Protection at <= 245.0 [deg C])
      * Nominal Cold Storage Pump Sump Delivery: 290.0 [deg C]
      * Nominal Superheated Receiver Delivery Header: 565.0 [deg C]
      * Salt Chemical Pyrolysis / Nitrite Dissociation Threshold: 588.0 [deg C] (SIL-3 Trip at 595.0 [deg C])
      * Alloy 617 / Haynes 230 Absorber Tube Crown Plastic Strain Limit: 640.0 [deg C]
  - Geodetic & Hydrodynamic Architecture:
      * Tower Vertical Riser Geodetic Elevation: 220.0 [m] (Static Head Delta_P ~ 39.9 bar)
      * Booster Pump: Multi-stage vertical can centrifugal pump with variable frequency drive (VFD)
      * Solar Flux Loading: Up to 950.0 [kW/m2] localized peak heat flux across North/East/West panels
      * Riser Flow Range: 12.5 [kg/s] (minimum anti-stratification flow) to 115.0 [kg/s] (full solar peak)
========================================================================================
 Cyber-Physical Control Synthesis:
  1. Triple Modular Redundancy (2oo3 TMR) Voting Engine for safety-critical thermohydraulic telemetry:
     - Cold salt inlet temperature (3x Class A PT100 RTDs)
     - Hot salt delivery temperature (3x Type-K ungrounded thermocouples in thermowells)
     - Booster pump suction head (3x ceramic piezoresistive differential transmitters)
  2. Temperature-Dependent Nonlinear Nitrate Salt Equation of State (EOS):
     - Dynamic computation of density (rho), specific heat (Cp), dynamic viscosity (mu), and conductivity (k)
     - Convective heat transfer coefficient (h_in) estimation via Gnielinski / Dittus-Boelter formulation
  3. Continuous 4-State Luenberger Thermal Observer for Absorber Tube Crown Temperature:
     - Real-time estimation of inaccessible front-tube outer wall metal skin temperatures
     - Prevention of film boiling, un-wetted tube burnout, and thermal fatigue cycling
  4. Non-linear Model Predictive & Feedforward Salt Mass Flow Synchronizer:
     - Dynamic thermal balance inversion coupling cavity absorbed radiant power to required mass flow
     - Fast DNI rate-of-change feedforward damping for cloud passage transient mitigation
  5. Centrifugal Pump Affinity Inversion for Synchronized VFD Shaft Speed Demand:
     - Inversion of pump H-Q characteristic against dynamic system resistance curve (static + friction)
  6. Minimum Safe Recirculation Bypass Control & Cavitation Suppression (NPSHa vs NPSHr tracking)
  7. Deterministic 9-Stage Sequencing Finite State Machine with Graceful Degradation & Emergency Aim-Off
========================================================================================
*)
VAR_INPUT
    bEnable                         : BOOL;     (* Master automation enable supervisory signal *)
    bEmergencyStop                  : BOOL;     (* Hardwired SIL-3 emergency trip line [Active Low] *)
    bResetFaults                    : BOOL;     (* Manual fault latch acknowledge and trip reset pulse *)
    rDNI_DirectNormalIrradiance     : REAL;     (* Fast pyrheliometer Direct Normal Irradiance [kW/m2] *)
    rFluxZone_North                 : REAL;     (* North cavity absorber panel peak heat flux [kW/m2] *)
    rFluxZone_East                  : REAL;     (* East cavity absorber panel peak heat flux [kW/m2] *)
    rFluxZone_West                  : REAL;     (* West cavity absorber panel peak heat flux [kW/m2] *)
    rSaltInletTemp_DegC_Ch1         : REAL;     (* Cold salt receiver inlet temperature - Ch1 [deg C] *)
    rSaltInletTemp_DegC_Ch2         : REAL;     (* Cold salt receiver inlet temperature - Ch2 [deg C] *)
    rSaltInletTemp_DegC_Ch3         : REAL;     (* Cold salt receiver inlet temperature - Ch3 [deg C] *)
    rSaltOutletTemp_DegC_Ch1        : REAL;     (* Hot salt receiver outlet temperature - Ch1 [deg C] *)
    rSaltOutletTemp_DegC_Ch2        : REAL;     (* Hot salt receiver outlet temperature - Ch2 [deg C] *)
    rSaltOutletTemp_DegC_Ch3        : REAL;     (* Hot salt receiver outlet temperature - Ch3 [deg C] *)
    rColdSaltSupplyPress_Ch1        : REAL;     (* Booster pump suction static pressure - Ch1 [bar] *)
    rColdSaltSupplyPress_Ch2        : REAL;     (* Booster pump suction static pressure - Ch2 [bar] *)
    rColdSaltSupplyPress_Ch3        : REAL;     (* Booster pump suction static pressure - Ch3 [bar] *)
    rBoosterDischargePress_bar      : REAL;     (* Booster pump discharge header pressure transmitter [bar] *)
    rSaltMassFlow_kg_s              : REAL;     (* Ultrasonic flowmeter molten salt mass flow rate [kg/s] *)
    rBoosterPumpSpeed_Act_rpm       : REAL;     (* Cold salt booster pump VFD encoder speed feedback [rpm] *)
    rTargetOutletTemp_DegC          : REAL;     (* Operator/Supervisory target molten salt outlet temperature [deg C] *)
    rAmbientTemp_DegC               : REAL;     (* Tower top cavity exterior ambient air temperature [deg C] *)
    rWindSpeed_m_s                  : REAL;     (* Tower top ultrasonic anemometer wind speed [m/s] *)
END_VAR

VAR_OUTPUT
    bSystemReady                    : BOOL;     (* Receiver circulation ready & heliostat aiming authorized *)
    bBoosterPumpRunCmd              : BOOL;     (* Cold salt booster pump variable speed drive run command *)
    rBoosterSpeedSetpoint_rpm       : REAL;     (* Cold salt booster pump synchronized VFD speed demand [rpm] *)
    rControlFlowDemand_kg_s         : REAL;     (* Predictive feedforward-feedback mass flow setpoint [kg/s] *)
    rBypassValveModulation_pct      : REAL;     (* Minimum flow recirculation bypass control valve modulation [%] *)
    rTubeCrownTempEst_DegC          : REAL;     (* Luenberger observer estimated peak tube crown temperature [deg C] *)
    rEffectiveAbsorbedThermalPower_MW : REAL;   (* Total net thermal power absorbed into molten salt flow [MW] *)
    bEmergencyDrainTrigger          : BOOL;     (* Fail-safe pneumatic receiver fast-drain dump valve trigger *)
    bHeliostatDefocusPermit         : BOOL;     (* Master optical safety interlock to heliostat field (TRUE=Track, FALSE=Aim-Off) *)
    wOperatingStatusWord            : WORD;     (* 16-bit packed discrete operating state status word *)
    dwDiagnosticAlarmWord           : DWORD;    (* 32-bit packed alarm, fault, and SIL trip diagnostic field *)
END_VAR

VAR
    (* State Machine & Sequencing Registers *)
    iMachineState                   : INT := 0;
    iPrevMachineState               : INT := 0;
    bInitDone                       : BOOL := FALSE;
    tStateTimer                     : TON;
    tPurgeTimer                     : TON;
    tSettlingTimer                  : TON;
    tDNI_DerivativeTimer            : TON;

    (* 2oo3 Triple Modular Redundancy Voting Registers: Cold Salt Inlet *)
    rInletTempVoted                 : REAL := 290.0;
    bInletCh1_Valid                 : BOOL := TRUE;
    bInletCh2_Valid                 : BOOL := TRUE;
    bInletCh3_Valid                 : BOOL := TRUE;
    bInletTemp_Degraded             : BOOL := FALSE;
    iInletValidCount                : INT := 3;

    (* 2oo3 Triple Modular Redundancy Voting Registers: Hot Salt Outlet *)
    rOutletTempVoted                : REAL := 565.0;
    bOutletCh1_Valid                : BOOL := TRUE;
    bOutletCh2_Valid                : BOOL := TRUE;
    bOutletCh3_Valid                : BOOL := TRUE;
    bOutletTemp_Degraded            : BOOL := FALSE;
    iOutletValidCount               : INT := 3;

    (* 2oo3 Triple Modular Redundancy Voting Registers: Booster Suction Pressure *)
    rSuctionPressVoted              : REAL := 3.5;
    bPressCh1_Valid                 : BOOL := TRUE;
    bPressCh2_Valid                 : BOOL := TRUE;
    bPressCh3_Valid                 : BOOL := TRUE;
    bPress_Degraded                 : BOOL := FALSE;
    iPressValidCount                : INT := 3;

    (* DNI Transient Observer & Flux Profile Aggregation *)
    rPrevDNI                        : REAL := 0.0;
    rDNI_RateOfChange_kW_m2_s       : REAL := 0.0;
    rDNI_FilteredRate               : REAL := 0.0;
    rAvgCavityFlux_kW_m2            : REAL := 0.0;
    rPeakCavityFlux_kW_m2           : REAL := 0.0;
    rFluxImbalanceRatio             : REAL := 1.0;

    (* Temperature-Dependent Nitrate Salt Thermophysical Evaluator *)
    rMeanSaltTemp_DegC              : REAL := 425.0;
    rSaltDensity_kg_m3              : REAL := 1850.0;
    rSaltCp_J_kgK                   : REAL := 1515.0;
    rSaltViscosity_Pa_s             : REAL := 0.0018;
    rSaltConductivity_W_mK          : REAL := 0.52;
    rSaltPrandtl                    : REAL := 5.24;
    rInternalReynolds               : REAL := 45000.0;
    rInternalNusselt                : REAL := 180.0;
    rInternalHTC_W_m2K              : REAL := 2500.0;

    (* Thermal Loss & Cavity Geometry Modeling *)
    rCavityApertureArea_m2          : REAL := 78.5;
    rEffectiveAbsorptance           : REAL := 0.945;
    rCavityEmissivity               : REAL := 0.88;
    rStefanBoltzmann                : REAL := 5.67037E-8;
    rRadHeatLoss_MW                 : REAL := 0.0;
    rConvHeatLoss_MW                : REAL := 0.0;
    rTotalHeatLoss_MW               : REAL := 0.0;
    rGrossIncidentPower_MW          : REAL := 0.0;
    rNetAbsorbedPower_MW            : REAL := 0.0;

    (* 4th-Order Discretized Thermal State Observer (x_thermal = [T_crown, T_inner, T_sublayer, T_bulk]) *)
    x_thermal                       : ARRAY[1..4] OF REAL := [480.0, 450.0, 430.0, 425.0];
    a_th                            : ARRAY[1..4, 1..4] OF REAL;
    b_th                            : ARRAY[1..4, 1..3] OF REAL;
    l_obs                           : ARRAY[1..4] OF REAL;
    q_solar_in_kW                   : REAL := 0.0;
    q_convective_loss_kW            : REAL := 0.0;
    q_salt_advection_kW             : REAL := 0.0;
    rObserverInnovation             : REAL := 0.0;

    (* Model Predictive Control & Feedforward Flux Synchronization Registers *)
    rFeedforwardFlow_kg_s           : REAL := 25.0;
    rFeedbackFlowCorrection_kg_s    : REAL := 0.0;
    rFlowErrorIntegral              : REAL := 0.0;
    rTempError                      : REAL := 0.0;
    rTargetSafeOutletTemp           : REAL := 565.0;
    rFlowRateLimiter_MaxStep        : REAL := 1.8;   (* Maximum flow ramp rate [kg/s per scan] *)
    rPrevFlowDemand_kg_s            : REAL := 25.0;

    (* Centrifugal Cold Salt Booster Pump Hydrodynamic Inversion Model *)
    rGeodeticHeight_m               : REAL := 220.0;
    rGravity_m_s2                   : REAL := 9.80665;
    rStaticHead_m                   : REAL := 220.0;
    rPipingFrictionCoeff            : REAL := 0.000125;
    rDynamicFrictionHead_m          : REAL := 12.0;
    rRequiredTotalDynamicHead_m     : REAL := 232.0;
    rVolumetricFlow_m3_s            : REAL := 0.0138;

    (* Pump Affinity Characteristic: H(N, Q) = c0*(N/N_nom)^2 - c1*(N/N_nom)*Q - c2*Q^2 *)
    rPumpNominalSpeed_rpm           : REAL := 1500.0;
    rPumpCoeff_c0                   : REAL := 285.0;
    rPumpCoeff_c1                   : REAL := 1200.0;
    rPumpCoeff_c2                   : REAL := 18500.0;
    rDiscrim                        : REAL := 0.0;
    rSpeedRatio                     : REAL := 0.85;
    rRawSpeedSetpoint_rpm           : REAL := 800.0;
    rClampedSpeedSetpoint_rpm       : REAL := 800.0;
    rPrevSpeedSetpoint_rpm          : REAL := 800.0;
    rSpeedRampRateLimit_rpm         : REAL := 25.0;  (* Max VFD speed acceleration [rpm per scan] *)

    (* Anti-Cavitation & NPSH Safety Tracking *)
    rSuctionStaticHead_m            : REAL := 15.0;
    rSaltVaporPress_bar             : REAL := 0.00001;
    rNPSH_Available_m               : REAL := 15.0;
    rNPSH_Required_m                : REAL := 4.2;

    (* Hydraulic Flow Limits *)
    rMinSafeMassFlow_kg_s           : REAL := 12.5;
    rMaxRatedMassFlow_kg_s          : REAL := 115.0;

    (* Diagnostic Delta Tracking & Iterators *)
    iIdx                            : INT := 1;
    jIdx                            : INT := 1;
    rMatAccum                       : REAL := 0.0;
    rDiff_12                        : REAL := 0.0;
    rDiff_23                        : REAL := 0.0;
    rDiff_31                        : REAL := 0.0;
END_VAR

(* ======================================================================================== *)
(* MATRIX PARAMETER INITIALIZATION (Discrete Linearized Thermal State Observer)            *)
(* ======================================================================================== *)
IF NOT bInitDone THEN
    (* System Transition Matrix A_th (4x4): Radial conduction across tube crown to core salt *)
    a_th[1, 1] := 0.8845;  a_th[1, 2] := 0.0982;  a_th[1, 3] := 0.0125;  a_th[1, 4] := 0.0048;
    a_th[2, 1] := 0.0765;  a_th[2, 2] := 0.8240;  a_th[2, 3] := 0.0815;  a_th[2, 4] := 0.0180;
    a_th[3, 1] := 0.0112;  a_th[3, 2] := 0.0954;  a_th[3, 3] := 0.7985;  a_th[3, 4] := 0.0949;
    a_th[4, 1] := 0.0035;  a_th[4, 2] := 0.0185;  a_th[4, 3] := 0.1120;  a_th[4, 4] := 0.8660;

    (* Input Coupling Matrix B_th (4x3): Inputs = [q_solar_in, q_convective_loss, q_salt_advection] *)
    b_th[1, 1] := 0.001850;  b_th[1, 2] := -0.000420;  b_th[1, 3] := -0.000085;
    b_th[2, 1] := 0.000410;  b_th[2, 2] := -0.000095;  b_th[2, 3] := -0.000210;
    b_th[3, 1] := 0.000085;  b_th[3, 2] := -0.000015;  b_th[3, 3] := -0.000680;
    b_th[4, 1] := 0.000025;  b_th[4, 2] := -0.000005;  b_th[4, 3] := -0.001420;

    (* Luenberger Observer Kalman Gains L_obs (4x1) for output error injection from outlet TMR *)
    l_obs[1] := 0.0450;
    l_obs[2] := 0.0985;
    l_obs[3] := 0.1650;
    l_obs[4] := 0.2850;

    rPrevDNI := rDNI_DirectNormalIrradiance;
    rPrevSpeedSetpoint_rpm := rBoosterPumpSpeed_Act_rpm;
    bInitDone := TRUE;
END_IF;

(* ======================================================================================== *)
(* SECTION 1: TRIPLE MODULAR REDUNDANCY (2oo3 TMR) SENSOR VOTING ENGINES                    *)
(* ======================================================================================== *)

(* --- 1.1 Cold Salt Inlet Temperature TMR Engine (Tolerance = 8.0 deg C) --- *)
rDiff_12 := ABS(rSaltInletTemp_DegC_Ch1 - rSaltInletTemp_DegC_Ch2);
rDiff_23 := ABS(rSaltInletTemp_DegC_Ch2 - rSaltInletTemp_DegC_Ch3);
rDiff_31 := ABS(rSaltInletTemp_DegC_Ch3 - rSaltInletTemp_DegC_Ch1);

bInletCh1_Valid := (rSaltInletTemp_DegC_Ch1 >= 220.0) AND (rSaltInletTemp_DegC_Ch1 <= 380.0) AND ((rDiff_12 <= 8.0) OR (rDiff_31 <= 8.0));
bInletCh2_Valid := (rSaltInletTemp_DegC_Ch2 >= 220.0) AND (rSaltInletTemp_DegC_Ch2 <= 380.0) AND ((rDiff_12 <= 8.0) OR (rDiff_23 <= 8.0));
bInletCh3_Valid := (rSaltInletTemp_DegC_Ch3 >= 220.0) AND (rSaltInletTemp_DegC_Ch3 <= 380.0) AND ((rDiff_23 <= 8.0) OR (rDiff_31 <= 8.0));

iInletValidCount := 0;
IF bInletCh1_Valid THEN iInletValidCount := iInletValidCount + 1; END_IF;
IF bInletCh2_Valid THEN iInletValidCount := iInletValidCount + 1; END_IF;
IF bInletCh3_Valid THEN iInletValidCount := iInletValidCount + 1; END_IF;

IF (iInletValidCount = 3) THEN
    (* Full 2oo3 Median Selection *)
    IF ((rSaltInletTemp_DegC_Ch1 >= rSaltInletTemp_DegC_Ch2) AND (rSaltInletTemp_DegC_Ch1 <= rSaltInletTemp_DegC_Ch3)) OR
       ((rSaltInletTemp_DegC_Ch1 <= rSaltInletTemp_DegC_Ch2) AND (rSaltInletTemp_DegC_Ch1 >= rSaltInletTemp_DegC_Ch3)) THEN
        rInletTempVoted := rSaltInletTemp_DegC_Ch1;
    ELSIF ((rSaltInletTemp_DegC_Ch2 >= rSaltInletTemp_DegC_Ch1) AND (rSaltInletTemp_DegC_Ch2 <= rSaltInletTemp_DegC_Ch3)) OR
          ((rSaltInletTemp_DegC_Ch2 <= rSaltInletTemp_DegC_Ch1) AND (rSaltInletTemp_DegC_Ch2 >= rSaltInletTemp_DegC_Ch3)) THEN
        rInletTempVoted := rSaltInletTemp_DegC_Ch2;
    ELSE
        rInletTempVoted := rSaltInletTemp_DegC_Ch3;
    END_IF;
    bInletTemp_Degraded := FALSE;
ELSIF (iInletValidCount = 2) THEN
    (* 2oo2 Averaging Degraded Fallback *)
    bInletTemp_Degraded := TRUE;
    IF bInletCh1_Valid AND bInletCh2_Valid THEN
        rInletTempVoted := (rSaltInletTemp_DegC_Ch1 + rSaltInletTemp_DegC_Ch2) * 0.5;
    ELSIF bInletCh2_Valid AND bInletCh3_Valid THEN
        rInletTempVoted := (rSaltInletTemp_DegC_Ch2 + rSaltInletTemp_DegC_Ch3) * 0.5;
    ELSE
        rInletTempVoted := (rSaltInletTemp_DegC_Ch1 + rSaltInletTemp_DegC_Ch3) * 0.5;
    END_IF;
ELSIF (iInletValidCount = 1) THEN
    (* 1oo1 Single Channel Emergency Fallback *)
    bInletTemp_Degraded := TRUE;
    IF bInletCh1_Valid THEN rInletTempVoted := rSaltInletTemp_DegC_Ch1;
    ELSIF bInletCh2_Valid THEN rInletTempVoted := rSaltInletTemp_DegC_Ch2;
    ELSE rInletTempVoted := rSaltInletTemp_DegC_Ch3;
    END_IF;
ELSE
    (* Total TMR Sensor Deprivation - Hold Last Safe Known Temperature *)
    bInletTemp_Degraded := TRUE;
END_IF;

(* --- 1.2 Hot Salt Outlet Temperature TMR Engine (Tolerance = 12.0 deg C) --- *)
rDiff_12 := ABS(rSaltOutletTemp_DegC_Ch1 - rSaltOutletTemp_DegC_Ch2);
rDiff_23 := ABS(rSaltOutletTemp_DegC_Ch2 - rSaltOutletTemp_DegC_Ch3);
rDiff_31 := ABS(rSaltOutletTemp_DegC_Ch3 - rSaltOutletTemp_DegC_Ch1);

bOutletCh1_Valid := (rSaltOutletTemp_DegC_Ch1 >= 250.0) AND (rSaltOutletTemp_DegC_Ch1 <= 620.0) AND ((rDiff_12 <= 12.0) OR (rDiff_31 <= 12.0));
bOutletCh2_Valid := (rSaltOutletTemp_DegC_Ch2 >= 250.0) AND (rSaltOutletTemp_DegC_Ch2 <= 620.0) AND ((rDiff_12 <= 12.0) OR (rDiff_23 <= 12.0));
bOutletCh3_Valid := (rSaltOutletTemp_DegC_Ch3 >= 250.0) AND (rSaltOutletTemp_DegC_Ch3 <= 620.0) AND ((rDiff_23 <= 12.0) OR (rDiff_31 <= 12.0));

iOutletValidCount := 0;
IF bOutletCh1_Valid THEN iOutletValidCount := iOutletValidCount + 1; END_IF;
IF bOutletCh2_Valid THEN iOutletValidCount := iOutletValidCount + 1; END_IF;
IF bOutletCh3_Valid THEN iOutletValidCount := iOutletValidCount + 1; END_IF;

IF (iOutletValidCount = 3) THEN
    IF ((rSaltOutletTemp_DegC_Ch1 >= rSaltOutletTemp_DegC_Ch2) AND (rSaltOutletTemp_DegC_Ch1 <= rSaltOutletTemp_DegC_Ch3)) OR
       ((rSaltOutletTemp_DegC_Ch1 <= rSaltOutletTemp_DegC_Ch2) AND (rSaltOutletTemp_DegC_Ch1 >= rSaltOutletTemp_DegC_Ch3)) THEN
        rOutletTempVoted := rSaltOutletTemp_DegC_Ch1;
    ELSIF ((rSaltOutletTemp_DegC_Ch2 >= rSaltOutletTemp_DegC_Ch1) AND (rSaltOutletTemp_DegC_Ch2 <= rSaltOutletTemp_DegC_Ch3)) OR
          ((rSaltOutletTemp_DegC_Ch2 <= rSaltOutletTemp_DegC_Ch1) AND (rSaltOutletTemp_DegC_Ch2 >= rSaltOutletTemp_DegC_Ch3)) THEN
        rOutletTempVoted := rSaltOutletTemp_DegC_Ch2;
    ELSE
        rOutletTempVoted := rSaltOutletTemp_DegC_Ch3;
    END_IF;
    bOutletTemp_Degraded := FALSE;
ELSIF (iOutletValidCount = 2) THEN
    bOutletTemp_Degraded := TRUE;
    IF bOutletCh1_Valid AND bOutletCh2_Valid THEN
        rOutletTempVoted := (rSaltOutletTemp_DegC_Ch1 + rSaltOutletTemp_DegC_Ch2) * 0.5;
    ELSIF bOutletCh2_Valid AND bOutletCh3_Valid THEN
        rOutletTempVoted := (rSaltOutletTemp_DegC_Ch2 + rSaltOutletTemp_DegC_Ch3) * 0.5;
    ELSE
        rOutletTempVoted := (rSaltOutletTemp_DegC_Ch1 + rSaltOutletTemp_DegC_Ch3) * 0.5;
    END_IF;
ELSIF (iOutletValidCount = 1) THEN
    bOutletTemp_Degraded := TRUE;
    IF bOutletCh1_Valid THEN rOutletTempVoted := rSaltOutletTemp_DegC_Ch1;
    ELSIF bOutletCh2_Valid THEN rOutletTempVoted := rSaltOutletTemp_DegC_Ch2;
    ELSE rOutletTempVoted := rSaltOutletTemp_DegC_Ch3;
    END_IF;
ELSE
    bOutletTemp_Degraded := TRUE;
END_IF;

(* --- 1.3 Booster Pump Suction Pressure TMR Engine (Tolerance = 0.45 bar) --- *)
rDiff_12 := ABS(rColdSaltSupplyPress_Ch1 - rColdSaltSupplyPress_Ch2);
rDiff_23 := ABS(rColdSaltSupplyPress_Ch2 - rColdSaltSupplyPress_Ch3);
rDiff_31 := ABS(rColdSaltSupplyPress_Ch3 - rColdSaltSupplyPress_Ch1);

bPressCh1_Valid := (rColdSaltSupplyPress_Ch1 >= 0.5) AND (rColdSaltSupplyPress_Ch1 <= 15.0) AND ((rDiff_12 <= 0.45) OR (rDiff_31 <= 0.45));
bPressCh2_Valid := (rColdSaltSupplyPress_Ch2 >= 0.5) AND (rColdSaltSupplyPress_Ch2 <= 15.0) AND ((rDiff_12 <= 0.45) OR (rDiff_23 <= 0.45));
bPressCh3_Valid := (rColdSaltSupplyPress_Ch3 >= 0.5) AND (rColdSaltSupplyPress_Ch3 <= 15.0) AND ((rDiff_23 <= 0.45) OR (rDiff_31 <= 0.45));

iPressValidCount := 0;
IF bPressCh1_Valid THEN iPressValidCount := iPressValidCount + 1; END_IF;
IF bPressCh2_Valid THEN iPressValidCount := iPressValidCount + 1; END_IF;
IF bPressCh3_Valid THEN iPressValidCount := iPressValidCount + 1; END_IF;

IF (iPressValidCount = 3) THEN
    IF ((rColdSaltSupplyPress_Ch1 >= rColdSaltSupplyPress_Ch2) AND (rColdSaltSupplyPress_Ch1 <= rColdSaltSupplyPress_Ch3)) OR
       ((rColdSaltSupplyPress_Ch1 <= rColdSaltSupplyPress_Ch2) AND (rColdSaltSupplyPress_Ch1 >= rColdSaltSupplyPress_Ch3)) THEN
        rSuctionPressVoted := rColdSaltSupplyPress_Ch1;
    ELSIF ((rColdSaltSupplyPress_Ch2 >= rColdSaltSupplyPress_Ch1) AND (rColdSaltSupplyPress_Ch2 <= rColdSaltSupplyPress_Ch3)) OR
          ((rColdSaltSupplyPress_Ch2 <= rColdSaltSupplyPress_Ch1) AND (rColdSaltSupplyPress_Ch2 >= rColdSaltSupplyPress_Ch3)) THEN
        rSuctionPressVoted := rColdSaltSupplyPress_Ch2;
    ELSE
        rSuctionPressVoted := rColdSaltSupplyPress_Ch3;
    END_IF;
    bPress_Degraded := FALSE;
ELSIF (iPressValidCount = 2) THEN
    bPress_Degraded := TRUE;
    IF bPressCh1_Valid AND bPressCh2_Valid THEN
        rSuctionPressVoted := (rColdSaltSupplyPress_Ch1 + rColdSaltSupplyPress_Ch2) * 0.5;
    ELSIF bPressCh2_Valid AND bPressCh3_Valid THEN
        rSuctionPressVoted := (rColdSaltSupplyPress_Ch2 + rColdSaltSupplyPress_Ch3) * 0.5;
    ELSE
        rSuctionPressVoted := (rColdSaltSupplyPress_Ch1 + rColdSaltSupplyPress_Ch3) * 0.5;
    END_IF;
ELSIF (iPressValidCount = 1) THEN
    bPress_Degraded := TRUE;
    IF bPressCh1_Valid THEN rSuctionPressVoted := rColdSaltSupplyPress_Ch1;
    ELSIF bPressCh2_Valid THEN rSuctionPressVoted := rColdSaltSupplyPress_Ch2;
    ELSE rSuctionPressVoted := rColdSaltSupplyPress_Ch3;
    END_IF;
ELSE
    bPress_Degraded := TRUE;
END_IF;

(* ======================================================================================== *)
(* SECTION 2: DYNAMIC THERMOPHYSICAL PROPERTIES EVALUATOR (Solar Salt 60/40)                *)
(* ======================================================================================== *)
rMeanSaltTemp_DegC := (rInletTempVoted + rOutletTempVoted) * 0.5;
IF rMeanSaltTemp_DegC < 230.0 THEN rMeanSaltTemp_DegC := 230.0; END_IF;
IF rMeanSaltTemp_DegC > 600.0 THEN rMeanSaltTemp_DegC := 600.0; END_IF;

(* Density correlation: rho(T) = 2090.0 - 0.636 * T [kg/m3] *)
rSaltDensity_kg_m3 := 2090.0 - (0.636 * rMeanSaltTemp_DegC);

(* Specific Heat correlation: Cp(T) = 1443.0 + 0.172 * T [J/(kg*K)] *)
rSaltCp_J_kgK := 1443.0 + (0.172 * rMeanSaltTemp_DegC);

(* Dynamic Viscosity correlation: mu(T) = 0.022714 - 1.20e-4*T + 2.281e-7*T^2 - 1.474e-10*T^3 [Pa*s] *)
rSaltViscosity_Pa_s := 0.022714 - (0.000120 * rMeanSaltTemp_DegC) 
                       + (0.0000002281 * (rMeanSaltTemp_DegC * rMeanSaltTemp_DegC)) 
                       - (0.0000000001474 * (rMeanSaltTemp_DegC * rMeanSaltTemp_DegC * rMeanSaltTemp_DegC));
IF rSaltViscosity_Pa_s < 0.0010 THEN rSaltViscosity_Pa_s := 0.0010; END_IF;

(* Thermal Conductivity: k(T) = 0.443 + 0.00019 * T [W/(m*K)] *)
rSaltConductivity_W_mK := 0.443 + (0.00019 * rMeanSaltTemp_DegC);

(* Dimensionless Thermohydraulic Numbers *)
rSaltPrandtl := (rSaltCp_J_kgK * rSaltViscosity_Pa_s) / rSaltConductivity_W_mK;
IF rSaltMassFlow_kg_s > 0.5 THEN
    (* Internal Reynolds Number: Re = (4 * m_dot) / (pi * D_hydraulic * mu) *)
    (* Internal tube diameter = 0.035 m (35 mm ID) with 48 parallel tube serpentine circuits *)
    rInternalReynolds := (4.0 * (rSaltMassFlow_kg_s / 48.0)) / (3.14159265 * 0.035 * rSaltViscosity_Pa_s);
    IF rInternalReynolds < 2300.0 THEN
        rInternalNusselt := 4.36; (* Laminar regime *)
    ELSE
        (* Gnielinski/Dittus-Boelter turbulent heat transfer correlation *)
        rInternalNusselt := 0.023 * EXPT(rInternalReynolds, 0.8) * EXPT(rSaltPrandtl, 0.4);
    END_IF;
    rInternalHTC_W_m2K := (rInternalNusselt * rSaltConductivity_W_mK) / 0.035;
ELSE
    rInternalHTC_W_m2K := 120.0;
END_IF;

(* ======================================================================================== *)
(* SECTION 3: CAVITY FLUX PROFILE AGGREGATION & RADIATIVE/CONVECTIVE LOSSES                 *)
(* ======================================================================================== *)
rAvgCavityFlux_kW_m2 := (rFluxZone_North + rFluxZone_East + rFluxZone_West) / 3.0;

(* Determine Localized Peak Heat Flux *)
rPeakCavityFlux_kW_m2 := rFluxZone_North;
IF rFluxZone_East > rPeakCavityFlux_kW_m2 THEN rPeakCavityFlux_kW_m2 := rFluxZone_East; END_IF;
IF rFluxZone_West > rPeakCavityFlux_kW_m2 THEN rPeakCavityFlux_kW_m2 := rFluxZone_West; END_IF;

(* Flux Imbalance Diagnostic Ratio *)
IF rAvgCavityFlux_kW_m2 > 1.0 THEN
    rFluxImbalanceRatio := rPeakCavityFlux_kW_m2 / rAvgCavityFlux_kW_m2;
ELSE
    rFluxImbalanceRatio := 1.0;
END_IF;

(* Gross Thermal Radiation Received at Cavity Aperture [MW] *)
rGrossIncidentPower_MW := (rAvgCavityFlux_kW_m2 * rCavityApertureArea_m2) * 0.001;

(* Cavity Re-radiation Loss to Ambient: P_rad = eps * sigma * A * (T_crown^4 - T_amb^4) [MW] *)
rRadHeatLoss_MW := rCavityEmissivity * rStefanBoltzmann * rCavityApertureArea_m2 
                   * (EXPT(x_thermal[1] + 273.15, 4.0) - EXPT(rAmbientTemp_DegC + 273.15, 4.0)) * 1.0E-6;
IF rRadHeatLoss_MW < 0.0 THEN rRadHeatLoss_MW := 0.0; END_IF;

(* Forced & Natural Convective Loss (Siebers-Kraabel Correlation) [MW] *)
rConvHeatLoss_MW := ((5.7 + (3.8 * rWindSpeed_m_s)) * rCavityApertureArea_m2 * (x_thermal[1] - rAmbientTemp_DegC)) * 1.0E-6;
IF rConvHeatLoss_MW < 0.0 THEN rConvHeatLoss_MW := 0.0; END_IF;

rTotalHeatLoss_MW := rRadHeatLoss_MW + rConvHeatLoss_MW;
rNetAbsorbedPower_MW := (rGrossIncidentPower_MW * rEffectiveAbsorptance) - rTotalHeatLoss_MW;
IF rNetAbsorbedPower_MW < 0.0 THEN rNetAbsorbedPower_MW := 0.0; END_IF;
rEffectiveAbsorbedThermalPower_MW := rNetAbsorbedPower_MW;

(* ======================================================================================== *)
(* SECTION 4: 4TH-ORDER LUENBERGER THERMAL OBSERVER (Tube Crown Metal Estimation)            *)
(* ======================================================================================== *)
(* Vector Inputs to State Space:
   u[1] = Solar flux heat input to tube outer crown [kW]
   u[2] = Exterior convective & radiative heat dissipation [kW]
   u[3] = Enthalpy advection heat transfer into flowing molten salt [kW]
*)
q_solar_in_kW := rPeakCavityFlux_kW_m2 * 1.25; (* Localized peak multiplier *)
q_convective_loss_kW := (rTotalHeatLoss_MW * 1000.0) / 48.0;
q_salt_advection_kW := (rSaltMassFlow_kg_s * rSaltCp_J_kgK * (x_thermal[4] - rInletTempVoted)) * 0.001;

(* Compute Observer Innovation Residual: e(k) = y_meas(k) - C * x_hat(k) *)
rObserverInnovation := rOutletTempVoted - x_thermal[4];

(* Thermal State Matrix Integration: x_th(k+1) = A_th * x_th(k) + B_th * u(k) + L_obs * e(k) *)
FOR iIdx := 1 TO 4 DO
    rMatAccum := 0.0;
    FOR jIdx := 1 TO 4 DO
        rMatAccum := rMatAccum + (a_th[iIdx, jIdx] * x_thermal[jIdx]);
    END_FOR;
    x_thermal[iIdx] := rMatAccum 
                      + (b_th[iIdx, 1] * q_solar_in_kW) 
                      + (b_th[iIdx, 2] * q_convective_loss_kW) 
                      + (b_th[iIdx, 3] * q_salt_advection_kW) 
                      + (l_obs[iIdx] * rObserverInnovation);
END_FOR;

(* Peak Outer Tube Wall Metal Skin Temperature Output *)
rTubeCrownTempEst_DegC := x_thermal[1];

(* ======================================================================================== *)
(* SECTION 5: MODEL PREDICTIVE FEEDFORWARD & FLUX SYNCHRONIZATION                           *)
(* ======================================================================================== *)
(* Fast Cloud Transient Observer via DNI Differential Filter *)
tDNI_DerivativeTimer(IN := TRUE, PT := T#100MS);
IF tDNI_DerivativeTimer.Q THEN
    rDNI_RateOfChange_kW_m2_s := (rDNI_DirectNormalIrradiance - rPrevDNI) / 0.100;
    rPrevDNI := rDNI_DirectNormalIrradiance;
    (* 1st-order low-pass noise filter on DNI derivative *)
    rDNI_FilteredRate := (0.75 * rDNI_FilteredRate) + (0.25 * rDNI_RateOfChange_kW_m2_s);
    tDNI_DerivativeTimer(IN := FALSE);
END_IF;

(* Constrain Supervisory Target Temperature to Prevent Nitrate Pyrolysis *)
rTargetSafeOutletTemp := rTargetOutletTemp_DegC;
IF rTargetSafeOutletTemp > 565.0 THEN rTargetSafeOutletTemp := 565.0; END_IF;
IF rTargetSafeOutletTemp < 450.0 THEN rTargetSafeOutletTemp := 450.0; END_IF;

(* Fundamental Thermodynamic Enthalpy Conservation Feedforward Flow:
   m_dot_ff = (P_net_MW * 1.0E6) / (Cp * (T_target - T_inlet))
*)
IF (rTargetSafeOutletTemp - rInletTempVoted) > 10.0 THEN
    rFeedforwardFlow_kg_s := (rNetAbsorbedPower_MW * 1.0E6) / (rSaltCp_J_kgK * (rTargetSafeOutletTemp - rInletTempVoted));
ELSE
    rFeedforwardFlow_kg_s := rMinSafeMassFlow_kg_s;
END_IF;

(* Predictive Cloud Transient Attenuation Feedforward *)
IF rDNI_FilteredRate < -0.040 THEN
    (* Rapidly incoming cloud: pre-emptively throttle flow rate to prevent severe tube chilling *)
    rFeedforwardFlow_kg_s := rFeedforwardFlow_kg_s * (1.0 + (rDNI_FilteredRate * 2.5));
END_IF;

(* Closed-Loop Feedback Trimming on Measured Hot Outlet Temperature *)
rTempError := rOutletTempVoted - rTargetSafeOutletTemp;
rFlowErrorIntegral := rFlowErrorIntegral + (0.015 * rTempError);
IF rFlowErrorIntegral > 15.0 THEN rFlowErrorIntegral := 15.0; END_IF;
IF rFlowErrorIntegral < -15.0 THEN rFlowErrorIntegral := -15.0; END_IF;

rFeedbackFlowCorrection_kg_s := (0.185 * rTempError) + rFlowErrorIntegral;

(* Combined Mass Flow Setpoint with Absolute Hydraulic Bounds *)
rControlFlowDemand_kg_s := rFeedforwardFlow_kg_s + rFeedbackFlowCorrection_kg_s;
IF rControlFlowDemand_kg_s < rMinSafeMassFlow_kg_s THEN
    rControlFlowDemand_kg_s := rMinSafeMassFlow_kg_s;
ELSIF rControlFlowDemand_kg_s > rMaxRatedMassFlow_kg_s THEN
    rControlFlowDemand_kg_s := rMaxRatedMassFlow_kg_s;
END_IF;

(* Dynamic Slew Rate Limiter to Eliminate Hydraulic Water-Hammer in 220m Vertical Riser *)
IF (rControlFlowDemand_kg_s - rPrevFlowDemand_kg_s) > rFlowRateLimiter_MaxStep THEN
    rControlFlowDemand_kg_s := rPrevFlowDemand_kg_s + rFlowRateLimiter_MaxStep;
ELSIF (rPrevFlowDemand_kg_s - rControlFlowDemand_kg_s) > rFlowRateLimiter_MaxStep THEN
    rControlFlowDemand_kg_s := rPrevFlowDemand_kg_s - rFlowRateLimiter_MaxStep;
END_IF;
rPrevFlowDemand_kg_s := rControlFlowDemand_kg_s;

(* ======================================================================================== *)
(* SECTION 6: CENTRIFUGAL BOOSTER PUMP HYDRODYNAMIC AFFINITY INVERSION                      *)
(* ======================================================================================== *)
(* Volumetric Flow Rate: Q = m_dot / rho [m3/s] *)
rVolumetricFlow_m3_s := rControlFlowDemand_kg_s / rSaltDensity_kg_m3;

(* Static Geodetic Head + Receiver System Dynamic Hydraulic Resistance *)
rStaticHead_m := rGeodeticHeight_m;
rDynamicFrictionHead_m := rPipingFrictionCoeff * (rControlFlowDemand_kg_s * rControlFlowDemand_kg_s) 
                          + ((rBoosterDischargePress_bar - (rSuctionPressVoted * 0.9)) * 1.0E5) / (rSaltDensity_kg_m3 * rGravity_m_s2);
IF rDynamicFrictionHead_m < 0.0 THEN rDynamicFrictionHead_m := 0.0; END_IF;

rRequiredTotalDynamicHead_m := rStaticHead_m + rDynamicFrictionHead_m;

(* Quadratic Inversion of Pump Affinity Law:
   H(N, Q) = c0 * alpha^2 - (c1 * Q) * alpha - (c2 * Q^2 + H_req) = 0
   where alpha = N / N_nom
*)
rDiscrim := ((rPumpCoeff_c1 * rVolumetricFlow_m3_s) * (rPumpCoeff_c1 * rVolumetricFlow_m3_s)) 
            + (4.0 * rPumpCoeff_c0 * (rRequiredTotalDynamicHead_m + (rPumpCoeff_c2 * rVolumetricFlow_m3_s * rVolumetricFlow_m3_s)));

IF rDiscrim >= 0.0 THEN
    rSpeedRatio := ((rPumpCoeff_c1 * rVolumetricFlow_m3_s) + SQRT(rDiscrim)) / (2.0 * rPumpCoeff_c0);
ELSE
    rSpeedRatio := 0.75;
END_IF;

rRawSpeedSetpoint_rpm := rSpeedRatio * rPumpNominalSpeed_rpm;

(* Speed Clamping within VFD Continuous Operating Boundaries *)
IF rRawSpeedSetpoint_rpm < 450.0 THEN
    rClampedSpeedSetpoint_rpm := 450.0;
ELSIF rRawSpeedSetpoint_rpm > 1780.0 THEN
    rClampedSpeedSetpoint_rpm := 1780.0;
ELSE
    rClampedSpeedSetpoint_rpm := rRawSpeedSetpoint_rpm;
END_IF;

(* Controlled VFD Acceleration/Deceleration Rate Limiter *)
IF (rClampedSpeedSetpoint_rpm - rPrevSpeedSetpoint_rpm) > rSpeedRampRateLimit_rpm THEN
    rBoosterSpeedSetpoint_rpm := rPrevSpeedSetpoint_rpm + rSpeedRampRateLimit_rpm;
ELSIF (rPrevSpeedSetpoint_rpm - rClampedSpeedSetpoint_rpm) > rSpeedRampRateLimit_rpm THEN
    rBoosterSpeedSetpoint_rpm := rPrevSpeedSetpoint_rpm - rSpeedRampRateLimit_rpm;
ELSE
    rBoosterSpeedSetpoint_rpm := rClampedSpeedSetpoint_rpm;
END_IF;
rPrevSpeedSetpoint_rpm := rBoosterSpeedSetpoint_rpm;

(* Minimum Recirculation Bypass Modulation: Ensures pump does not operate below minimum flow *)
IF rControlFlowDemand_kg_s < (rMinSafeMassFlow_kg_s * 1.5) THEN
    rBypassValveModulation_pct := (( (rMinSafeMassFlow_kg_s * 1.5) - rControlFlowDemand_kg_s ) / (rMinSafeMassFlow_kg_s * 0.5)) * 100.0;
    IF rBypassValveModulation_pct > 100.0 THEN rBypassValveModulation_pct := 100.0; END_IF;
ELSE
    rBypassValveModulation_pct := 0.0;
END_IF;

(* Anti-Cavitation Net Positive Suction Head (NPSHa vs NPSHr) Monitoring *)
rSuctionStaticHead_m := (rSuctionPressVoted * 1.0E5) / (rSaltDensity_kg_m3 * rGravity_m_s2);
rNPSH_Available_m := rSuctionStaticHead_m - ((rSaltVaporPress_bar * 1.0E5) / (rSaltDensity_kg_m3 * rGravity_m_s2));
rNPSH_Required_m := 3.2 + (1.8 * (rBoosterSpeedSetpoint_rpm / rPumpNominalSpeed_rpm) * (rBoosterSpeedSetpoint_rpm / rPumpNominalSpeed_rpm));

(* ======================================================================================== *)
(* SECTION 7: DETERMINISTIC 9-STAGE FINITE STATE MACHINE (FSM)                              *)
(* ======================================================================================== *)
tStateTimer(IN := (iMachineState = iPrevMachineState), PT := T#120S);
tSettlingTimer(IN := (iMachineState = 20 OR iMachineState = 30), PT := T#5S);
tPurgeTimer(IN := (iMachineState = 10), PT := T#15S);
iPrevMachineState := iMachineState;

CASE iMachineState OF
    0: (* STATE_POWER_ON_SELF_TEST_AND_STANDBY *)
        bSystemReady := FALSE;
        bBoosterPumpRunCmd := FALSE;
        bEmergencyDrainTrigger := FALSE;
        bHeliostatDefocusPermit := FALSE;
        rBoosterSpeedSetpoint_rpm := 0.0;
        IF bEnable AND bEmergencyStop AND (iInletValidCount >= 2) AND (iOutletValidCount >= 2) AND (iPressValidCount >= 2) THEN
            iMachineState := 10; (* Advance to Trace Heat Verification *)
        END_IF;

    10: (* STATE_TRACE_HEAT_VERIFICATION_AND_PURGE *)
        bSystemReady := FALSE;
        bBoosterPumpRunCmd := FALSE;
        bEmergencyDrainTrigger := FALSE;
        bHeliostatDefocusPermit := FALSE;
        (* Verify receiver piping and headers are pre-heated above salt freezing knee *)
        IF (rInletTempVoted >= 260.0) AND (rOutletTempVoted >= 260.0) AND tPurgeTimer.Q THEN
            iMachineState := 20; (* Advance to Priming and Head Buildup *)
        ELSIF (rInletTempVoted < 250.0) OR (rOutletTempVoted < 250.0) THEN
            (* Riser or receiver too cold; lock in pre-warm *)
            iMachineState := 10;
        END_IF;

    20: (* STATE_RISER_PRIMING_AND_HEAD_BUILDUP *)
        bSystemReady := FALSE;
        bBoosterPumpRunCmd := TRUE;
        bEmergencyDrainTrigger := FALSE;
        bHeliostatDefocusPermit := FALSE;
        rBoosterSpeedSetpoint_rpm := 650.0; (* Priming crawl speed *)
        IF tSettlingTimer.Q THEN
            IF (rBoosterDischargePress_bar >= 28.0) AND (rSaltMassFlow_kg_s >= rMinSafeMassFlow_kg_s) THEN
                iMachineState := 30; (* Advance to Recirculation Standby *)
            ELSIF (rBoosterDischargePress_bar < 18.0) THEN
                iMachineState := 99; (* Priming failure / vapor lock trip *)
            END_IF;
        END_IF;

    30: (* STATE_RECIRCULATION_STANDBY_MIN_FLOW *)
        bSystemReady := TRUE;
        bBoosterPumpRunCmd := TRUE;
        bEmergencyDrainTrigger := FALSE;
        bHeliostatDefocusPermit := TRUE; (* Heliostats may acquire standby optical aim-points *)
        IF (rAvgCavityFlux_kW_m2 > 35.0) AND (rDNI_DirectNormalIrradiance > 0.150) THEN
            iMachineState := 40; (* Solar flux detected, advance to Active Tracking *)
        ELSIF bInletTemp_Degraded OR bOutletTemp_Degraded THEN
            iMachineState := 60; (* Degraded TMR Contingency *)
        END_IF;

    40: (* STATE_ACTIVE_SOLAR_FLUX_SYNC_MPC *)
        bSystemReady := TRUE;
        bBoosterPumpRunCmd := TRUE;
        bEmergencyDrainTrigger := FALSE;
        bHeliostatDefocusPermit := TRUE;
        IF (rDNI_FilteredRate < -0.050) THEN
            iMachineState := 50; (* Cloud transient detected, engage fast damping *)
        ELSIF (rAvgCavityFlux_kW_m2 < 20.0) AND (rDNI_DirectNormalIrradiance < 0.100) THEN
            iMachineState := 30; (* Sunset / overcast drop back to Standby *)
        ELSIF bInletTemp_Degraded OR bOutletTemp_Degraded OR bPress_Degraded THEN
            iMachineState := 60; (* Sensor degradation contingency *)
        END_IF;

    50: (* STATE_CLOUD_TRANSIENT_FAST_DAMPING *)
        bSystemReady := TRUE;
        bBoosterPumpRunCmd := TRUE;
        bEmergencyDrainTrigger := FALSE;
        bHeliostatDefocusPermit := TRUE;
        (* Maintain minimum safe cooling while waiting for cloud passage *)
        IF (rDNI_FilteredRate >= -0.010) AND (rAvgCavityFlux_kW_m2 >= 30.0) THEN
            iMachineState := 40; (* Cloud cleared, return to full MPC tracking *)
        ELSIF (rDNI_DirectNormalIrradiance < 0.080) AND tStateTimer.Q THEN
            iMachineState := 90; (* Persistent overcast, initiate controlled shutdown *)
        END_IF;

    60: (* STATE_DEGRADED_TMR_CONTINGENCY *)
        bSystemReady := TRUE;
        bBoosterPumpRunCmd := TRUE;
        bEmergencyDrainTrigger := FALSE;
        bHeliostatDefocusPermit := TRUE;
        (* Apply 15% conservative flow safety factor during sensor degradation *)
        rControlFlowDemand_kg_s := rControlFlowDemand_kg_s * 1.15;
        IF (iInletValidCount < 2) OR (iOutletValidCount < 2) OR (iPressValidCount < 2) THEN
            iMachineState := 99; (* Insufficient valid channels for SIL-2 integrity *)
        ELSIF NOT bInletTemp_Degraded AND NOT bOutletTemp_Degraded AND NOT bPress_Degraded THEN
            iMachineState := 40; (* Full redundancy restored *)
        END_IF;

    90: (* STATE_CONTROLLED_SYSTEM_DRAIN_COOLDOWN *)
        bSystemReady := FALSE;
        bBoosterPumpRunCmd := FALSE;
        bEmergencyDrainTrigger := FALSE;
        bHeliostatDefocusPermit := FALSE; (* Immediate field defocus *)
        rBoosterSpeedSetpoint_rpm := 0.0;
        IF (rOutletTempVoted < 340.0) THEN
            bEmergencyDrainTrigger := TRUE; (* Open gravity drain to base tank *)
            IF (rSaltMassFlow_kg_s < 1.0) THEN
                iMachineState := 0; (* System completely drained *)
            END_IF;
        END_IF;

    99: (* STATE_EMERGENCY_DEFOCUS_AND_DUMP *)
        bSystemReady := FALSE;
        bBoosterPumpRunCmd := FALSE;
        rBoosterSpeedSetpoint_rpm := 0.0;
        bHeliostatDefocusPermit := FALSE; (* HARD TRIP: Immediate emergency aim-off *)
        bEmergencyDrainTrigger := TRUE;   (* Rapid gravitational dump to prevent explosion / freezing *)
        IF bResetFaults AND bEmergencyStop AND (rOutletTempVoted < 575.0) AND (x_thermal[1] < 600.0) THEN
            bEmergencyDrainTrigger := FALSE;
            iMachineState := 0; (* Manual reset acknowledged *)
        END_IF;

    ELSE
        iMachineState := 99;
END_CASE;

(* ======================================================================================== *)
(* SECTION 8: HARDWIRED SAFETY INTERLOCKS & CRITICAL TRIP OVERRIDES                         *)
(* ======================================================================================== *)
(* 8.1 SIL-3 Emergency Stop Master Trip *)
IF NOT bEmergencyStop THEN
    iMachineState := 99;
    bHeliostatDefocusPermit := FALSE;
    bEmergencyDrainTrigger := TRUE;
END_IF;

(* 8.2 Nitrate Salt Decomposition Trip (> 595.0 deg C) *)
IF (rOutletTempVoted > 595.0) THEN
    iMachineState := 99;
    bHeliostatDefocusPermit := FALSE;
    bEmergencyDrainTrigger := TRUE;
END_IF;

(* 8.3 Tube Crown Peak Thermal Burnout Limit (> 635.0 deg C) *)
IF (x_thermal[1] > 635.0) THEN
    iMachineState := 99;
    bHeliostatDefocusPermit := FALSE;
    bEmergencyDrainTrigger := TRUE;
END_IF;

(* 8.4 Salt Solidification Freeze Lockout (< 245.0 deg C while running) *)
IF (rInletTempVoted < 245.0) AND (iMachineState >= 20) THEN
    iMachineState := 99;
    bHeliostatDefocusPermit := FALSE;
    bEmergencyDrainTrigger := TRUE;
END_IF;

(* 8.5 Loss of Flow during Active Solar Irradiation *)
IF (rAvgCavityFlux_kW_m2 > 150.0) AND (rSaltMassFlow_kg_s < rMinSafeMassFlow_kg_s) AND (iMachineState >= 30) THEN
    iMachineState := 99;
    bHeliostatDefocusPermit := FALSE;
    bEmergencyDrainTrigger := TRUE;
END_IF;

(* 8.6 Booster Pump Cavitation Interlock (NPSHa < NPSHr) *)
IF (rNPSH_Available_m < rNPSH_Required_m) AND (iMachineState >= 20) THEN
    (* Severe cavitation detected, shed pump load *)
    rBoosterSpeedSetpoint_rpm := 450.0;
END_IF;

(* ======================================================================================== *)
(* SECTION 9: 16-BIT PACKED OPERATING STATUS WORD COMPILATION                               *)
(* ======================================================================================== *)
wOperatingStatusWord.0  := bSystemReady;
wOperatingStatusWord.1  := bBoosterPumpRunCmd;
wOperatingStatusWord.2  := (iMachineState = 40); (* Normal MPC Solar Tracking *)
wOperatingStatusWord.3  := (iMachineState = 50); (* Cloud Transient Fast Damping *)
wOperatingStatusWord.4  := (iMachineState = 60); (* Degraded Redundancy Active *)
wOperatingStatusWord.5  := bHeliostatDefocusPermit;
wOperatingStatusWord.6  := bEmergencyDrainTrigger;
wOperatingStatusWord.7  := (rBypassValveModulation_pct > 1.0);
wOperatingStatusWord.8  := bInletTemp_Degraded;
wOperatingStatusWord.9  := bOutletTemp_Degraded;
wOperatingStatusWord.10 := bPress_Degraded;
wOperatingStatusWord.11 := (rNPSH_Available_m < (rNPSH_Required_m + 1.5));
wOperatingStatusWord.12 := (rFluxImbalanceRatio > 1.35);
wOperatingStatusWord.13 := (iMachineState = 90); (* Cooldown active *)
wOperatingStatusWord.14 := (iMachineState = 99); (* Trip latched *)
wOperatingStatusWord.15 := bInitDone;

(* ======================================================================================== *)
(* SECTION 10: 32-BIT COMPREHENSIVE DIAGNOSTIC ALARM & FAULT FIELD                          *)
(* ======================================================================================== *)
dwDiagnosticAlarmWord.0  := NOT bEmergencyStop;
dwDiagnosticAlarmWord.1  := NOT bInletCh1_Valid;
dwDiagnosticAlarmWord.2  := NOT bInletCh2_Valid;
dwDiagnosticAlarmWord.3  := NOT bInletCh3_Valid;
dwDiagnosticAlarmWord.4  := (iInletValidCount < 2);
dwDiagnosticAlarmWord.5  := NOT bOutletCh1_Valid;
dwDiagnosticAlarmWord.6  := NOT bOutletCh2_Valid;
dwDiagnosticAlarmWord.7  := NOT bOutletCh3_Valid;
dwDiagnosticAlarmWord.8  := (iOutletValidCount < 2);
dwDiagnosticAlarmWord.9  := NOT bPressCh1_Valid;
dwDiagnosticAlarmWord.10 := NOT bPressCh2_Valid;
dwDiagnosticAlarmWord.11 := NOT bPressCh3_Valid;
dwDiagnosticAlarmWord.12 := (iPressValidCount < 2);
dwDiagnosticAlarmWord.13 := (rInletTempVoted < 260.0);   (* Cold Salt Inlet Low Warning *)
dwDiagnosticAlarmWord.14 := (rInletTempVoted < 245.0);   (* Cold Salt Solidification SIL Trip *)
dwDiagnosticAlarmWord.15 := (rOutletTempVoted > 575.0);  (* Hot Salt High Temp Warning *)
dwDiagnosticAlarmWord.16 := (rOutletTempVoted > 595.0);  (* Hot Salt Thermal Pyrolysis Trip *)
dwDiagnosticAlarmWord.17 := (x_thermal[1] > 610.0);      (* Tube Crown Metal High Warning *)
dwDiagnosticAlarmWord.18 := (x_thermal[1] > 635.0);      (* Tube Crown Plastic Burnout Trip *)
dwDiagnosticAlarmWord.19 := (rPeakCavityFlux_kW_m2 > 900.0); (* Extreme Localized Flux Warning *)
dwDiagnosticAlarmWord.20 := (rFluxImbalanceRatio > 1.50); (* Severe Cavity Thermal Skew *)
dwDiagnosticAlarmWord.21 := (rSaltMassFlow_kg_s < rMinSafeMassFlow_kg_s) AND (iMachineState >= 30);
dwDiagnosticAlarmWord.22 := (rBoosterDischargePress_bar < 20.0) AND (iMachineState >= 20);
dwDiagnosticAlarmWord.23 := (rNPSH_Available_m < rNPSH_Required_m); (* Pump Cavitation Trip *)
dwDiagnosticAlarmWord.24 := (rSuctionPressVoted < 1.0);  (* Low Suction Supply Pressure *)
dwDiagnosticAlarmWord.25 := (rWindSpeed_m_s > 25.0);     (* High Tower Cross-Wind Warning *)
dwDiagnosticAlarmWord.26 := (rDNI_FilteredRate < -0.060); (* Severe Cloud Shock Dynamic *)
dwDiagnosticAlarmWord.27 := (iMachineState = 99);        (* Emergency Latched Lockout *)
dwDiagnosticAlarmWord.28 := (ABS(rSaltMassFlow_kg_s - rControlFlowDemand_kg_s) > 12.0); (* Flow Tracking Error *)
dwDiagnosticAlarmWord.29 := (rBoosterPumpSpeed_Act_rpm > 1820.0); (* Booster Overspeed *)
dwDiagnosticAlarmWord.30 := FALSE;
dwDiagnosticAlarmWord.31 := FALSE;

END_FUNCTION_BLOCK
